/// <summary>
/// <c>METSalesDocumentPostingService</c> is a service class to post sales document.
/// </summary>
public class METSalesDocumentPostingService extends METSysOperationServiceBase
{
    container                               conShipmentId;
    container                               conDocStatus;
    container                               conAccountOrder;
    DocumentStatus                          docStatus;
    METSalesDocumentPostingDataContract     dataContractLocal;
    AccountOrder                            accountOrder;
    Counter                                 conLenCounter;


}

Method.Source:
/// <summary>
/// Process method to initiate business logic
/// </summary>
protected void process()
{
    for(conLenCounter = 1; conLen(conShipmentId) >= conLenCounter; conLenCounter++)
    {
        this.invoke();
    }

    DocumentStatus  docStatusMsg    = conPeek(conDocStatus,1);

    batchHeader.parmCaption(strFmt("@MET:ShipmentMsg", docStatusMsg, conPeek(conShipmentId,1)));
    batchHeader.save();
}

/// <summary>
/// Initilialise variables
/// </summary>
/// <param name = "_dataContract">Contact class reference</param>
protected void init(METSysOperationServiceBaseDataContract _dataContract)
{
    super(_dataContract);

    dataContractLocal = _dataContract;

    conShipmentId   = dataContractLocal.parmShipmentIdList();
    conDocStatus    = dataContractLocal.parmDocStatusList();
    conAccountOrder = dataContractLocal.parmAccountOrderList();
}

/// <summary>
/// Construct method to initiate task
/// </summary>
/// <returns>SysOperationServiceController</returns>
protected SysOperationServiceController constructTask()
{
    SysOperationServiceController           controller;
    METSalesDocumentPostingDataContract     contract;

    controller = new SysOperationServiceController(classstr(METSalesDocumentPostingTask),
                            methodstr(METSalesDocumentPostingTask, run),
                            SysOperationExecutionMode::Synchronous);

    contract = controller.getDataContractObject();

    contract.parmDocStatus(conPeek(conDocStatus, conLenCounter));
    contract.parmShipmentId(conPeek(conShipmentId, conLenCounter));
    contract.parmAccountOrder(conPeek(conAccountOrder, conLenCounter));

    return controller;
}

/// <summary>
/// Set caption for task
/// </summary>
/// <returns>Caption</returns>
protected Description getCaption()
{
    return ' ';
}

/// <summary>
/// run method for contract
/// </summary>
/// <param name = "_dataContract">Contract reference</param>
[METSysOperationDataContractNameAttribute(classstr(METSalesDocumentPostingDataContract))]
void run(METSysOperationServiceBaseDataContract _dataContract)
{
    Super(_dataContract);
}
